export type DataTypes = Record<string, unknown>;
export interface Message<METADATA = unknown, DATA extends DataTypes = DataTypes> {
    id: string;
    metadata?: METADATA;
    data?: DATA;
}
/** A bare `Message` bound: every instantiation in TypeScript, one in F#. */
export interface EndEvent<M extends Message> {
    message: M;
    isAborted: boolean;
}
/** Applies `EndEvent` to a variable bounded by another instantiation of `Message`. */
export interface Transport<M extends Message<unknown, never>> {
    last: EndEvent<M>;
}
/** The options object reads `METADATA` only through `M`'s bound. */
export declare function stream<METADATA = unknown, M extends Message<METADATA, never> = Message<METADATA, never>>(options: {
    messages: M[];
    transport: Transport<M>;
}): void;
